def update_contenttypes_and_permissions(apps, schema_editor):
    """
    Update ContentType and Permissions for ModerationReason model
    after moving it from 'petition' app to 'moderation' app.
    """

    # Old and new app labels
    old_app = "petition"
    new_app = "signatures"
    model = "signatures"

    # 1) content_type
    try:
        ct = ContentType.objects.get(app_label=old_app, model=model)
        ct.app_label = new_app
        ct.save(update_fields=["app_label"])
    except ContentType.DoesNotExist:
        # If the content type does not exist, nothing to update
        pass

    # 2) permissions
    try:
        new_ct = ContentType.objects.get(app_label=new_app, model=model)
        Permission.objects.filter(
            content_type__app_label=old_app, content_type__model=model
        ).update(content_type=new_ct)
    except ContentType.DoesNotExist:
        pass


